def name_months_alike(apps, schema_editor):
    """Whole-month periods were named two ways ("May 2026" from an old seed,
    "2026-10" from the Create button). Name them all YYYY-MM."""
    FinancialPeriod = apps.get_model('hw', 'FinancialPeriod')
    for p in FinancialPeriod.objects.all():
        is_month = p.date_from.day == 1 and p.date_to == p.date_from + relativedelta(months=1, days=-1)
        name = f'{p.date_from.year}-{p.date_from.month:02d}'
        if is_month and p.name != name and not FinancialPeriod.objects.filter(name=name).exists():
            p.name = name
            p.save(update_fields=['name'])


